// Map HexBlockType to ItemType (what you get when mining)
function blockToItem(blockType: HexBlockType): ItemType {
  switch (blockType) {
    case HexBlockType.STONE: return ItemType.STONE;
    case HexBlockType.DIRT: return ItemType.DIRT;
    case HexBlockType.GRASS: return ItemType.DIRT; // Grass drops dirt, not grass
    case HexBlockType.WOOD: return ItemType.WOOD;
    case HexBlockType.SAND: return ItemType.SAND;
    // Mineral ores
    case HexBlockType.ORE_COAL: return ItemType.ORE_COAL;
    case HexBlockType.ORE_COPPER: return ItemType.ORE_COPPER;
    case HexBlockType.ORE_IRON: return ItemType.ORE_IRON;
    case HexBlockType.ORE_GOLD: return ItemType.ORE_GOLD;
    case HexBlockType.ORE_LITHIUM: return ItemType.ORE_LITHIUM;
    case HexBlockType.ORE_ALUMINUM: return ItemType.ORE_ALUMINUM;
    case HexBlockType.ORE_COBALT: return ItemType.ORE_COBALT;
    // Snow biome blocks
    case HexBlockType.SNOW: return ItemType.SNOW;
    case HexBlockType.DIRT_SNOW: return ItemType.DIRT; // Dirt with snow drops dirt
    case HexBlockType.ICE: return ItemType.ICE;
    // Glass
    case HexBlockType.GLASS: return ItemType.GLASS;
    // Advanced technology blocks
    case HexBlockType.COMPUTER: return ItemType.COMPUTER;
    case HexBlockType.PRINTER_3D: return ItemType.PRINTER_3D;
    // Moon terrain
    case HexBlockType.MOON_ROCK: return ItemType.MOON_ROCK;
    // Sequoia terrain
    case HexBlockType.SEQ_GRASS: return ItemType.SEQ_DIRT; // Like grass, drops its soil
    case HexBlockType.SEQ_DIRT: return ItemType.SEQ_DIRT;
    case HexBlockType.SEQ_SAND: return ItemType.SEQ_SAND;
    case HexBlockType.SEQ_SNOW: return ItemType.SEQ_SNOW;
    // Biome surfaces drop their soil, as grass does
    case HexBlockType.FOREST_FLOOR: return ItemType.DIRT;
    case HexBlockType.DRY_GRASS: return ItemType.DIRT;
    case HexBlockType.SEQ_SCRUB: return ItemType.SEQ_DIRT;
    case HexBlockType.SEQ_DUFF: return ItemType.SEQ_DIRT;
    // The living alien worlds' grounds drop the planet's rock (its soil:
    // MOON_ROCK is a single-texture world's native rock)
    case HexBlockType.CINDER_EMBERMOSS: case HexBlockType.CINDER_ASH: case HexBlockType.CINDER_SULFUR:
    case HexBlockType.VESPER_DUNE: case HexBlockType.VESPER_SALT:
    case HexBlockType.HALCYON_MOSS: case HexBlockType.HALCYON_GEODE: case HexBlockType.HALCYON_GLASS:
    case HexBlockType.TESSALY_SNOWMOSS: case HexBlockType.TESSALY_FROST: case HexBlockType.TESSALY_GLAZE:
    case HexBlockType.UMBRA_MOSS: case HexBlockType.UMBRA_MYCEL: case HexBlockType.UMBRA_SHALE:
      return ItemType.MOON_ROCK;
    // The jungle moons: their grounds and soil drop dirt, their rock stone
    case HexBlockType.VERD_JUNGLE: case HexBlockType.VERD_SWAMP: case HexBlockType.VERD_SOIL:
    case HexBlockType.MIRE_JUNGLE: case HexBlockType.MIRE_SWAMP: case HexBlockType.MIRE_SOIL:
    case HexBlockType.THAL_TURF: case HexBlockType.THAL_MOSS: case HexBlockType.THAL_SOIL:
      return ItemType.DIRT;
    case HexBlockType.VERD_BANK: case HexBlockType.MIRE_BANK: case HexBlockType.THAL_BANK: return ItemType.SAND;
    case HexBlockType.VERD_ROCK: case HexBlockType.MIRE_ROCK: case HexBlockType.THAL_ROCK: return ItemType.STONE;
    // The Moon's minerals give the ordinary ores
    case HexBlockType.MOON_ORE_IRON: return ItemType.ORE_IRON;
    case HexBlockType.MOON_ORE_ALUMINUM: return ItemType.ORE_ALUMINUM;
    case HexBlockType.MOON_ORE_COBALT: return ItemType.ORE_COBALT;
    case HexBlockType.MOON_ORE_LITHIUM: return ItemType.ORE_LITHIUM;
    // ...and titanium, which only the Moon has
    case HexBlockType.MOON_ORE_TITANIUM: return ItemType.ORE_TITANIUM;
    // The city is built of stone and glass; its park lawns are soil
    case HexBlockType.CITY_ROAD:
    case HexBlockType.CITY_SIDEWALK:
    case HexBlockType.CITY_PLAZA:
    case HexBlockType.CITY_FACADE:
    case HexBlockType.CITY_ROOF:
    case HexBlockType.CITY_METAL:
    case HexBlockType.CITY_FOUNDATION: return ItemType.STONE;
    case HexBlockType.CITY_GLASS:
    case HexBlockType.CITY_NEON: return ItemType.GLASS;
    case HexBlockType.CITY_PARK: return ItemType.DIRT;
    // A street lamp gives its light back as a torch
    case HexBlockType.CITY_LAMP: return ItemType.TORCH;
    // Moons and asteroids: volcanic rock gives basalt (magma cools as it is
    // dug), frost and glacier ice give ice for fuel, meteoric iron gives iron
    case HexBlockType.BASALT: return ItemType.BASALT;
    case HexBlockType.LAVA_ROCK: return ItemType.BASALT;
    case HexBlockType.MAGMA: return ItemType.BASALT;
    case HexBlockType.SULFUR: return ItemType.SULFUR;
    case HexBlockType.FROST: return ItemType.ICE;
    case HexBlockType.BLUE_ICE: return ItemType.ICE;
    case HexBlockType.IRON_NICKEL: return ItemType.ORE_IRON;
    // Industry resources: clay (Earth's, and Vesper's clay ground - it is
    // clay), uranium ore; oil sand comes out whole, for the refinery (a
    // bucket still scoops crude straight from it)
    case HexBlockType.CLAY: case HexBlockType.VESPER_CLAY: return ItemType.CLAY;
    case HexBlockType.ORE_URANIUM: return ItemType.ORE_URANIUM;
    // Body resources (space-exploration): mined, never placed back
    case HexBlockType.RESIN_AMBER: return ItemType.RESIN;
    case HexBlockType.SALVAGE_SCRAP: return ItemType.SALVAGE;
    case HexBlockType.ORE_RARE_EARTH: return ItemType.RARE_EARTH_ORE;
    case HexBlockType.FUNGUS_SEAM: return ItemType.RADIOTROPHIC_FUNGUS;
    case HexBlockType.SILICA_SAND: return ItemType.SILICA;
    case HexBlockType.CRYSTAL_VEIN: return ItemType.CRYSTAL;
    case HexBlockType.CRYO_ICE: return ItemType.CRYO_COOLANT;
    case HexBlockType.OIL_SAND: return ItemType.OIL_SAND;
    // Building materials come back as themselves
    case HexBlockType.BRICK_BLOCK: return ItemType.BRICK_BLOCK;
    case HexBlockType.CARPET: return ItemType.CARPET;
    case HexBlockType.CONCRETE_BLOCK: return ItemType.CONCRETE_BLOCK;
    case HexBlockType.STEEL_GIRDER: return ItemType.STEEL_GIRDER;
    case HexBlockType.STEEL_GLASS: return ItemType.STEEL_GLASS;
    default: return ItemType.NONE;
  }
}

// Map ItemType to HexBlockType (what block to place)
function itemToBlock(itemType: ItemType): HexBlockType {
  switch (itemType) {
    case ItemType.STONE: return HexBlockType.STONE;
    case ItemType.DIRT: return HexBlockType.DIRT;
    case ItemType.GRASS: return HexBlockType.DIRT; // Grass items place as dirt (grass isn't placeable)
    case ItemType.WOOD: return HexBlockType.WOOD;
    case ItemType.SAND: return HexBlockType.SAND;
    // Mineral ores can be placed back
    case ItemType.ORE_COAL: return HexBlockType.ORE_COAL;
    case ItemType.ORE_COPPER: return HexBlockType.ORE_COPPER;
    case ItemType.ORE_IRON: return HexBlockType.ORE_IRON;
    case ItemType.ORE_GOLD: return HexBlockType.ORE_GOLD;
    case ItemType.ORE_LITHIUM: return HexBlockType.ORE_LITHIUM;
    case ItemType.ORE_ALUMINUM: return HexBlockType.ORE_ALUMINUM;
    case ItemType.ORE_COBALT: return HexBlockType.ORE_COBALT;
    case ItemType.ORE_TITANIUM: return HexBlockType.MOON_ORE_TITANIUM;
    // Snow biome blocks can be placed
    case ItemType.SNOW: return HexBlockType.SNOW;
    case ItemType.ICE: return HexBlockType.ICE;
    // Glass can be placed
    case ItemType.GLASS: return HexBlockType.GLASS;
    // Moon terrain can be placed
    case ItemType.MOON_ROCK: return HexBlockType.MOON_ROCK;
    // Sequoia terrain can be placed anywhere and keeps its look
    case ItemType.SEQ_DIRT: return HexBlockType.SEQ_DIRT;
    case ItemType.SEQ_SAND: return HexBlockType.SEQ_SAND;
    case ItemType.SEQ_SNOW: return HexBlockType.SEQ_SNOW;
    case ItemType.BASALT: return HexBlockType.BASALT;
    case ItemType.SULFUR: return HexBlockType.SULFUR;
    case ItemType.CLAY: return HexBlockType.CLAY;
    case ItemType.OIL_SAND: return HexBlockType.OIL_SAND;
    case ItemType.ORE_URANIUM: return HexBlockType.ORE_URANIUM;
    case ItemType.BRICK_BLOCK: return HexBlockType.BRICK_BLOCK;
    case ItemType.CARPET: return HexBlockType.CARPET;
    case ItemType.CONCRETE_BLOCK: return HexBlockType.CONCRETE_BLOCK;
    case ItemType.STEEL_GIRDER: return HexBlockType.STEEL_GIRDER;
    case ItemType.STEEL_GLASS: return HexBlockType.STEEL_GLASS;
    default: return HexBlockType.AIR;
  }
}

// An electric furnace's save record: the one shape both save points write
function electricFurnaceSave(f: PlacedElectricFurnace): Omit<SavedElectricFurnace, 'tileIndex'> {
  return {
    position: { x: f.position.x, y: f.position.y, z: f.position.z },
    rotation: f.rotation,
    smeltingItem: f.smeltingItem,
    smeltingProgress: f.smeltingProgress,
    inputCount: f.inputCount,
    additiveItem: f.additiveItem,
    additiveCount: f.additiveCount,
    outputItem: f.outputItem,
    outputCount: f.outputCount,
  };
}

// Every kind of saved world object, in load order (machines before the
// cables that connect them), with where its saves live
/**
 * A list with the object an open panel shows first: a panel action saves
 * every machine of its kind, and the action's inventory trade goes on the
 * first record that changed (openspec mp-shared-objects) - which must be the
 * one the player used, not one the planet's host just advanced.
 */
function openFirst<T>(list: T[], open: T | null): T[] {
  return open && list.includes(open) ? [open, ...list.filter(o => o !== open)] : list;
}

// A placed object as the multiplayer record appliers handle it
type WorldObject = { position: THREE.Vector3 };

/** A 3D printer's jobs and output tray from its saved record (a load and an MP record both read it here). */
function printerStateFromSave(saved: SavedPrinter3D): Pick<PlacedPrinter3D, 'currentJob' | 'printQueue'> & { outputInventory: PrinterOutputSlot[] | null } {
  const ingredients = (obj?: Record<string, number>): Map<ItemType, number> =>
    new Map<ItemType, number>(Object.entries(obj ?? {}).map(([k, v]) => [parseInt(k) as ItemType, v]));
  const job = saved.currentJob;
  return {
    currentJob: job ? {
      itemType: job.itemType as ItemType,
      progress: job.progress,
      totalTime: job.totalTime,
      startTime: job.startTime,
      outputQuantity: job.outputQuantity || 1,
      ingredients: ingredients(job.ingredients),
    } : null,
    printQueue: saved.printQueue?.map(q => ({
      itemType: q.itemType as ItemType,
      totalTime: q.totalTime,
      outputQuantity: q.outputQuantity,
      ingredients: ingredients(q.ingredients),
    })) ?? [],
    outputInventory: saved.outputInventory?.map(sl => ({ itemType: sl.itemType as ItemType | null, quantity: sl.quantity })) ?? null,
  };
}

