  // Get planet ID for saving (identifies which planet)
  private getPlanetId(planet: Planet): string {
    return planet.getName();
  }

  // Get neighbor tile indices for pipe connection detection
  private getNeighborTileIndices(tileIndex: number, near?: THREE.Vector3): number[] {
    // Tile indices repeat from planet to planet: with a position, use its planet
    const on = near ? this.planetOf(near) : undefined;
    if (on) return (on.getTileByIndex(tileIndex)?.neighbors as number[] | undefined) ?? [];
    // Find which planet has this tile
    for (const planet of this.planets) {
      const tile = planet.getTileByIndex(tileIndex);
      if (tile && tile.neighbors) {
        // neighbors is already an array of tile indices (numbers)
        return tile.neighbors as number[];
      }
    }
    return [];
  }

  // Save inventory to local storage
  /**
   * One use off the tool that digs a block dropping `drop` (none if bare
   * hands did it). A broken tool toasts; the inventory saves this frame.
   */
  private wearToolFor(drop: ItemType): void {
    const { toolIndex } = mineTimeMult(this.inventory, drop);
    if (toolIndex !== null) this.wearSlot(toolIndex);
  }

  /** One use off the tool in a slot (a dig, a cast): toast if it broke, save now. */
  public wearSlot(index: number): void {
    const w = wearAt(this.inventory, index);
    if (w.kind === 'none') return;
    if (w.kind === 'broke') showToast(brokeMessage(w), { duration: TOOLBOX.TOAST_MS });
    this.updateHotbarUI();
    this.saveInventory();
  }

